#!/usr/bin/env bash
# Builds the test plugins' components from their core modules and the world in
# assets/wit, written out as text the tests read. Needs wasm-tools.
set -euo pipefail
cd "$(dirname "$0")"
wit=../../../../assets/wit
tmp=$(mktemp -d)
trap 'rm -rf "$tmp"' EXIT
for name in lookup plain; do
  wasm-tools component embed "$wit" --world processor "$name.module.wat" -o "$tmp/$name.core.wasm"
  wasm-tools component new "$tmp/$name.core.wasm" -o "$tmp/$name.wasm"
  wasm-tools strip --all "$tmp/$name.wasm" -o "$tmp/$name.stripped.wasm"
  {
    echo ";; Generated by make.sh from $name.module.wat; do not edit."
    wasm-tools print "$tmp/$name.stripped.wasm"
  } > "$name.component.wat"
done
